#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    const long long MOD = 1000000007;
    vector<long long> count(n + 1, 0);
    count[0] = 1;
    for (long long m = 1; m <= n; m++) {
        long long total = 0;
        for (long long left = 0; left < m; left++) {
            total = (total + count[left] * count[m - 1 - left]) % MOD;
        }
        count[m] = total;
    }
    cout << count[n] << "\n";

    return 0;
}

